game_activity_reset_confirm: "Azzera",
game_activity_reset_explain: "Questa operazione elimina definitivamente il tempo di gioco registrato da ps5upload su questa console. Non può essere annullata e le sessioni passate non sono recuperabili. I registri della console non vengono toccati: viene cancellato solo ciò che mostra questa schermata.",
