imgbrowse_title: "Guarda dentro un'immagine",
imgbrowse_explain: "Sfoglia qualsiasi immagine di gioco o pacchetto letto da ps5upload (.exfat, .ffpkg, .ffpfs, .ffpfsc, o un .pkg creato con la chiave di debug) su qualsiasi computer, senza montarlo. Salva un file o una cartella sul computer, oppure modifica i file e scrivi una copia modificata: l'immagine aperta non viene mai cambiata.",
