imgbrowse_change_delete: "Elimina {path}",
imgbrowse_change_put: "Metti {from} in {path}",
imgbrowse_undo: "Annulla",
imgbrowse_copy_explain: "La copia è un'immagine completamente nuova dello stesso tipo, scritta accanto all'originale con -edited nel nome, poi riletta e verificata. Richiede circa lo stesso tempo della conversione del gioco. L'originale non viene modificato.",
imgbrowse_write_copy: "Scrivi copia modificata",
imgbrowse_discard: "Scarta le modifiche",
imgbrowse_writing_copy: "Scrittura di una copia modificata di {name}",
imgbrowse_copy_done: "Copia modificata scritta e verificata",
imgbrowse_open_copy: "Guarda dentro la copia",
localimage_explain: "Apre l'immagine come una normale unità su questo computer, così puoi aggiungere, sostituire ed eliminare i file al suo interno — le patch, per esempio — con il Finder o Esplora file, esattamente come su una chiavetta USB. Le modifiche vengono salvate direttamente nel file immagine. ps5upload non scrive mai nell'immagine; lo fa il tuo sistema operativo. Espellila da qui quando hai finito.",
localimage_filter: "Immagini disco",
localimage_none_hint: "Scegli un file .exfat o .img per aprirlo come unità.",
localimage_not_mounted: "collegata, ma non è stato possibile montarne nulla",
