"pack_inspect": "Controlla",
"pack_found": "{libs} librerie, {mods} file sce_module — {size}",
"pack_other_ignored": "Altri {count} file nella cartella non fanno parte di un backport e non verranno toccati.",
"pack_not_a_pack": "Nessuna cartella fakelib/ qui, quindi non è un pacchetto di backport.",
"pack_mismatch_title": "Questo pacchetto indica un altro gioco",
"pack_mismatch_body": "La cartella dice {pack}, ma stai installando in {target}. L installazione sostituisce l eboot di questo gioco con quello dell altro.",
