"fpkg.lowSpace": "Poco spazio libero: la conversione può richiedere fino a {need} sull’unità di destinazione, che ne ha {free}.",
"fpkg.about": "Indica una cartella di gioco, o un’immagine di montaggio .exfat o .ffpkg. Il convertitore legge l’albero, verifica che ci sia tutto ciò che serve a un pacchetto avviabile e scrive un .pkg in formato debug nella cartella di destinazione.",
"fpkg.aboutWhere": "La conversione gira sulla macchina che ospita il motore — questo computer, un host Docker o un dispositivo Android — non sulla console. Nulla arriva alla console finché non installi il pacchetto: in streaming da questo computer, o caricandolo prima sulla PS5.",
"fpkg.aboutSource": "La sorgente deve essere un albero di gioco già decifrato. Un’installazione retail non può essere estratta qui, e il controllo qui sotto lo dirà se è quello che hai scelto.",
"fpkg.aboutChecks": "Cosa verifica il controllo",
"fpkg.checkEboot": "Un eboot.bin nella radice dell’albero: il modulo del titolo. Deve essere un ELF grezzo o un SELF incapsulato; un modulo firmato retail non può essere reimpacchettato.",
"fpkg.checkParam": "sce_sys/param.json, e nessun sce_sys/param.sfo: un param.sfo manda il percorso di avvio della console sulla via PS4.",
"fpkg.checkIcons": "Un ID contenuto di 36 caratteri, entrambe le icone e il modulo dei diritti sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Che il valore DRM del pacchetto sia standard. Un valore gratuito o aggiornabile fa bloccare il titolo dalla console; viene riscritto solo nel pacchetto e il tuo file non viene mai toccato.",
"payloads_essentials_title": "Consigliati insieme a ps5upload",
"payloads_essentials_body": "Se stai configurando una console per la prima volta, questi tre coprono quasi tutto ciò che ps5upload si aspetta di trovare: kstuff-lite (patch del kernel su cui si basa la maggior parte dell’homebrew), ShadowMount+ (monta immagini di gioco dalla memoria) e nanoDNS (tiene la console lontana dagli aggiornamenti di Sony). Tutto il resto dell’elenco è facoltativo.",
