library_download_resume: "Riprendi download",
kept_title: "Conservato da ps5upload",
kept_intro: "Le cartelle che ps5upload scrive su questa console e quanto contiene ciascuna. I file temporanei e di prova si possono ripulire; i tuoi pacchetti e i backup dei salvataggi da qui si aprono soltanto, non vengono mai eliminati.",
kept_measuring: "Misurazione…",
kept_nothing: "ps5upload non conserva nulla su questa console.",
kept_pkg_library: "Libreria pacchetti",
kept_pkg_temp: "File temporanei dei pacchetti",
kept_backups: "Backup dei salvataggi",
kept_tests: "File di prova",
kept_at_least: "almeno {size}",
kept_files: "{count} file",
kept_clean: "Ripulisci",
kept_open: "Apri in File",
kept_clean_title: "Eliminare questi file dalla PS5?",
kept_clean_body: "Tutto il contenuto di {path} ({size}) verrà eliminato. Sono residui che ps5upload può ricreare; la libreria pacchetti e i backup dei salvataggi non vengono toccati.",
library_move_retry: "Riprova lo spostamento",
volumes_pkg_copies_here: "Le copie dei pacchetti sono qui",
volumes_store_pkg_copies: "Salva qui le copie dei pacchetti",
volumes_pkg_copies_hint: "Cosa fa questa scelta: «Carica e installa» copia prima il file .pkg sulla PS5, poi installa da quella copia. Qui si decide solo su quale unità stanno quelle copie. Non cambia dove vengono installati i giochi (lo decide la PS5 nelle sue impostazioni di archiviazione), e «Trasmetti e installa» non conserva alcuna copia. Se l'unità scelta non è collegata, le copie vanno nella memoria interna.",
saves_auto_folder_label: "Cartella di backup",
captures: "Screenshot e clip",
captures_title: "Acquisizioni",
"arcpkg.choose": "Scegli archivio…",
"arcpkg.help": "Per un .zip, .7z o .rar che contiene uno o più file .pkg, in qualsiasi cartella. Vengono estratti solo i pacchetti, direttamente sulla PS5 (su questo computer non viene estratto nulla), poi installati uno alla volta: il gioco base prima del suo aggiornamento, poi i DLC. Un RAR in più parti (.part1.rar, .part2.rar…) funziona: scegli la prima parte e tieni le altre accanto. La password viene chiesta quando un RAR la richiede; ZIP e 7z protetti da password non sono supportati.",
"arcpkg.keepsRunning": "Continua anche se apri un'altra schermata; compare anche in Attività.",
"arcpkg.notArchive": "Quel file non è un archivio .zip, .7z o .rar.",
"arcpkg.pick": "Scegli un archivio",
"arcpkg.title": "Installa pacchetti da un archivio",
"install.library.title": "Copie dei pacchetti sulla PS5",
"install.stream.file.help": "Scegli un .pkg o .fpkg, oppure trascinane uno in un punto qualsiasi di questa finestra. Tieni aperta l'app finché l'installazione non finisce; l'avanzamento è nella coda qui sopra e in Attività.",
"install.stream.file.title": "Installa un file pacchetto",
"install.tab.stream.lead": "La PS5 installa direttamente da questo computer o da un link. Prima non viene messa alcuna copia sulla PS5, quindi lì non serve spazio libero, ed è il modo più affidabile di installare.",
"install.tab.upload.lead": "Il pacchetto viene prima copiato sulla PS5 e poi installato da quella copia. Usalo quando la PS5 non riesce a raggiungere questo computer (Trasmetti fallisce con un errore di rete), o per tenere i pacchetti sulla PS5 e reinstallarli più tardi senza questo computer.",
"install.upload.file.browser": "Per copiare un pacchetto sulla PS5 da qui serve l'app desktop. Nell'interfaccia web usa Trasmetti e installa, oppure installa qui sotto i pacchetti già presenti sulla PS5.",
"install.upload.file.help": "Scegli un .pkg o .fpkg. La copia richiede spazio libero sulla PS5 per l'intero pacchetto e resta nell'elenco qui sotto finché non la rimuovi.",
"install.upload.file.title": "Copia un pacchetto sulla PS5 e installalo",
"linkcard.confirm.direct": "La PS5 scarica da sola il pacchetto dal link e lo installa. Questo computer non serve più una volta avviato, e l'avanzamento si vede sulla PS5 (Download), non qui. Se la PS5 non riesce a recuperare il link, l'app lo trasmette attraverso questo computer. Reinstallare sopra un gioco installato può rimuoverlo se l'installer di Sony fallisce. Usa solo link a pacchetti di cui ti fidi e che sei autorizzato a installare.",
"linkcard.confirm.download": "Questo computer salva prima l'intero pacchetto sul disco, poi lo installa sulla PS5. Deve restare acceso finché entrambe le fasi non finiscono e ha bisogno di spazio libero per il pacchetto. Reinstallare sopra un gioco installato può rimuoverlo se l'installer di Sony fallisce. Usa solo link a pacchetti di cui ti fidi e che sei autorizzato a installare.",
"linkcard.confirm.stream": "Questo computer scarica il pacchetto e lo passa direttamente alla PS5, quindi deve restare acceso e connesso finché l'installazione non finisce. Sul disco non viene salvato nulla. Reinstallare sopra un gioco installato può rimuoverlo se l'installer di Sony fallisce. Usa solo link a pacchetti di cui ti fidi e che sei autorizzato a installare.",
"linkcard.confirm.title": "Installare da questo link?",
"linkcard.fact.awake": "Tieni acceso questo computer",
"linkcard.fact.can_close": "Puoi chiudere l'app",
"linkcard.fact.disk": "Serve spazio su disco qui",
"linkcard.fact.no_disk": "Non serve spazio su disco",
"linkcard.fact.progress_here": "Avanzamento mostrato qui",
"linkcard.fact.progress_ps5": "Avanzamento sulla PS5",
"linkcard.forget": "Rimuovi dall'elenco",
"linkcard.help": "Incolla un link di download diretto a un .pkg. Prima non viene copiato nulla sulla PS5, quindi un gioco da 100 GB non richiede spazio extra lì.",
"linkcard.how": "Come va recuperato?",
"linkcard.insecure": "Salta il controllo del certificato",
"linkcard.insecure_hint": "Per il tuo server, o un sito con il certificato scaduto. Vale qui perché è questo computer a stabilire la connessione.",
"linkcard.install": "Installa dal link",
"linkcard.mode.direct": "Lo scarica la PS5",
"linkcard.mode.direct_body": "La PS5 recupera il link da sola. Deve poter raggiungere il link e l'indirizzo deve essere corto (l'app ne accorcia uno lungo e in quel caso deve restare aperta).",
"linkcard.mode.download": "Scarica prima qui, poi installa",
"linkcard.mode.download_body": "Questo computer salva l'intero pacchetto, poi lo installa. È il più lento, ma un link che scade o si interrompe a metà costa solo un nuovo tentativo di download.",
"linkcard.mode.stream": "Trasmetti attraverso questo computer",
"linkcard.mode.stream_body": "Questo computer scarica su più connessioni e passa i dati direttamente alla PS5. Di solito è il più veloce e funziona quando solo questo computer può raggiungere il link.",
"linkcard.name": "Nome (facoltativo)",
"linkcard.name_hint": "Il nome compare nella coda, in Attività e in Link recenti al posto dell'indirizzo, così distingui i link e riprovi quello giusto.",
"linkcard.name_placeholder": "es. Astro Bot aggiornamento 1.05",
