"share.note.package": "Il pacchetto viene trasmesso alla PS5 e installato. Prima non viene copiato nulla sulla PS5.",
"share.note.archive": "L’archivio si apre in Installa pacchetti da un archivio, che elenca i pacchetti contenuti. Installali da lì.",
"share.note.copy": "Solo l’app che l’ha condiviso può leggere questo file, quindi viene prima copiato in questa app (fino a {limit}).",
