"share.unsupported": "PS5Upload installa pacchetti .pkg e .fpkg e archivi ZIP, 7z o RAR. Questo non è nessuno di questi.",
"share.too_large": "Questo file supera {limit}, troppo grande per copiarlo nell’app. Scaricalo prima sul telefono (per esempio in Download), poi condividilo di nuovo dall’app File.",
"share.no_space": "Sul telefono non c’è abbastanza spazio libero per copiarlo nell’app.",
