"share.remote_engine": "Questa app usa un motore su un altro computer, che non può aprire file di questo.",
"share.not_connected": "Connettiti prima a una PS5. Resta qui in attesa finché non lo invii o annulli.",
"install.description.v2": "Installa pacchetti .pkg e .fpkg sulla tua PS5: direttamente da questo computer o da un link (Trasmetti e installa), oppure da una copia messa prima sulla PS5 (Carica e installa).",
