a11y_dyslexia_hint_v2: "Usa Atkinson Hyperlegible o OpenDyslexic se uno dei due è installato su questo dispositivo (nessuno è incluso nell'app), con una spaziatura tra lettere e righe leggermente più ampia. Senza nessuno dei due cambia solo la spaziatura.",
a11y_motion_hint_v2: "Auto segue l'impostazione del sistema operativo. Ridotte disattiva l'animazione di cambio schermata e accorcia quelle dei pop-up; Nessuna disattiva tutte le animazioni e le transizioni.",
a11y_transparency: "Riduci trasparenza",
