about_feat_install_body: "File .pkg PS4 e pacchetti fake PS5 (base, aggiornamento, DLC) da questo computer, una condivisione NAS, un'unità USB o un link. Se la PS5 rifiuta un metodo, l'app ne propone un altro.",
about_feat_install_title: "Installa pacchetti",
