"fpkg.image.lz4_no_ampr": "Questo gioco non legge i file tramite AMPR, quindi nulla potrebbe servire i pacchetti. Comprimilo invece in un .ffpfsc: ShadowMount+ lo decomprime per qualsiasi gioco.",
"fpkg.image.verify_chunk": "Controllo di rilettura, per lettura",
