"install_help_what_means": "Cosa significa?",
"install_help_wont_launch": "Il gioco non si avvia?",
install_hint_setup_exe: "Il programma di installazione si è aperto: seguilo e aggiornerà PS5Upload sul posto.",
install_path_fallback_hint: "Un'ultima risorsa per un pacchetto già presente sulla PS5, quando la PS5 lo rifiuta dalla propria memoria e non riesce nemmeno a prenderlo da questo computer. Usata solo per un gioco base non installato, quindi non può rimuovere nulla. Non verificata: ha funzionato sul firmware 11.20 ed è rifiutata su 13.60. Se la provi, segnala per favore se ha funzionato.",
install_path_fallback_label: "Installa tramite percorso del file quando la PS5 non riesce a raggiungere questo computer",
"installed_fix_permissions": "Correggi permessi: rendi la cartella di questo gioco leggibile ed eseguibile dalla PS5 (chmod 777)",
