"minion_lan_hint": "Disattivato: lo apre solo il browser della PS5 stessa. Attivato: anche un telefono, un tablet o un computer sulla stessa rete può aprirlo, quindi chiunque sia su quella rete. Attivalo solo a casa.",
"minion_open_here": "Apri qui",
"minion_remove_note": "Rimuovi disattiva Minion ed elimina ciò che conserva sulla PS5: i preferiti e le cartelle recenti di File, la cache della Libreria dei giochi e il log del controller. Condivisioni di rete, cheat e backup restano; li usa anche l’app per PC.",
