"minion_remove_title": "Rimuovere PS5Upload Minion?",
"minion_remove_confirm": "Il suo riquadro nella schermata Home e la sua pagina spariscono, e i suoi file sulla PS5 vengono eliminati. L’helper lo mantiene disattivato da ora in poi. Puoi riattivarlo qui in qualsiasi momento.",
"minion_remove_go": "Rimuovi",
"minion_removed_done": "Minion è stato rimosso: il suo riquadro e la sua pagina non ci sono più e {n} suoi file sulla PS5 sono stati eliminati. Resta disattivato, anche dopo il riavvio dell’helper, finché non lo riattivi qui.",
