"rp_fit_short_fit": "Adatta",
"rp_fit_short_fill": "Riempi",
"rp_set_next_start_v2": "Risoluzione e frequenza dei fotogrammi si applicano al prossimo avvio. La dimensione dell'immagine si applica subito; si vede a schermo intero, dove la forma dello schermo può differire da quella dell'immagine.",
"rp_browser_best": "Gioca funziona meglio in Chrome o Edge",
"rp_browser_firefox": "In Firefox, Esc esce sempre dallo schermo intero, quindi lì non può essere il ○ del controller, e il picture-in-picture non è disponibile.",
"rp_browser_safari": "In Safari, Esc esce sempre dallo schermo intero, quindi lì non può essere il ○ del controller, e il picture-in-picture mostra solo l'immagine.",
"rp_browser_other": "È fatto e provato per loro. Qui Esc come ○ del controller a schermo intero e il picture-in-picture potrebbero non funzionare.",
"rp_browser_other_mobile": "È fatto e provato per Chrome su Android.",
