"rp_keep_10m": "10 minuti",
"rp_keep_hint": "Le altre schermate mantengono lo stream attivo; questo è quanto attende quando nessuna finestra lo mostra (chiusa o ricaricata) prima di terminare.",
"rp_game_mode_mac": "Mentre giochi, il computer e lo schermo restano attivi. Lo schermo intero attiva anche la modalità Gioco (macOS 14 e successivi).",
"rp_game_mode_ios": "La modalità Gioco si attiva mentre l'app occupa lo schermo (iOS e iPadOS 18 e successivi).",
"rp_game_mode_windows": "Mentre giochi, il computer e lo schermo restano attivi. Windows non permette a un'app di attivare la modalità Gioco; vedi le FAQ.",
"rp_game_mode_linux": "Mentre giochi, il computer e lo schermo restano attivi e GameMode (gamemoded) si attiva se è installato.",
"rp_game_mode_android": "Mentre giochi, lo schermo resta acceso, il dispositivo mantiene una velocità costante quando può e a un televisore via HDMI viene chiesta la sua modalità gioco.",
"rp_set_controls": "Controlli",
"rp_capture_pointer": "Fare clic sull'immagine nasconde il puntatore",
"rp_capture_pointer_hint": "Esc lo mostra di nuovo.",
"rp_rumble": "Vibrazione del controller",
"rp_dualsense": "Effetti DualSense",
"rp_dualsense_hint": "Con un DualSense collegato a questo computer: grilletti adattivi e, collegato via USB, feedback aptico. Vale dal prossimo avvio.",
"rp_mic_setting": "Microfono (sperimentale)",
"rp_mic_setting_hint": "Aggiunge un pulsante microfono per la chat vocale. Vale dal prossimo avvio.",
"rp_touch_controls": "Controller su schermo",
