"rp_touch_on": "Sempre",
"rp_touch_off": "Mai",
"rp_controls_hint": "Funziona anche un controller: collegalo o abbinalo a questo dispositivo. Shift + trascina sull'immagine è un dito sul touchpad.",
"rp_hid_touchpad": "Usa il touchpad del DualSense",
"rp_hid_touchpad_hint": "Il browser chiede quale controller: scegli il DualSense.",
"rp_hid_touchpad_on": "Il touchpad del DualSense viene letto in questo browser.",
"rp_settings": "Impostazioni",
"rp_running_elsewhere": "Gioca è in uso su {name}",
"rp_show_here": "Mostra qui",
"rp_running_elsewhere_body": "È stato avviato da un'altra finestra o prima che la pagina si ricaricasse, ed è ancora in corso.",
"rpg_user_title": "Accedi con un utente sulla PS5",
"rpg_user_body": "Sulla console scegli l'utente con cui giocherai. Non serve che qualcuno resti davanti allo schermo, ma l'utente deve aver effettuato l'accesso. Usa un utente senza codice di accesso: un codice blocca l'accesso automatico quando la console si riattiva.",
"rpg_account_title": "Dai a quell'utente un ID account",
"rpg_account_body": "Remote Play si associa tramite un ID account. Un utente collegato a PlayStation Network ne ha già uno; un utente offline deve averne uno impostato in Utenti qui sopra (va bene qualsiasi ID; annotalo, i salvataggi fatti dopo sono legati a esso).",
"rpg_signin_title": "Fai accedere l'account a PlayStation Network (offline)",
"rpg_signin_body": "La PS5 consente Remote Play solo a un account connesso. Se l'impostazione Riproduzione Remota della console è disattivata (grigia), esegui l'accesso offline qui sotto (non viene inviato nulla a Sony), poi riavvia la PS5. Si può annullare.",
"rpg_signin_fix": "Vai all'accesso",
"rpg_service_title": "Attiva Remote Play",
"rpg_service_body": "Impostazioni › Sistema › Riproduzione Remota › Abilita Riproduzione Remota. L'app può attivarla per te e, dal firmware 10.00 in poi, consentirla anche per questo utente. Se poi Avvia dice che Remote Play è disattivato, attivalo nelle Impostazioni della PS5 stessa: conta l'interruttore della console.",
"rpg_rest_title": "Consenti di riattivare la PS5 dalla modalità riposo",
"rpg_rest_body": "Impostazioni › Sistema › Risparmio energetico › Funzioni disponibili in modalità riposo: attiva «Rimani connesso a Internet» e «Abilita l'accensione della PS5 dalla rete». Senza di esse una console in modalità riposo non si può riattivare e la sua rete si spegne dopo pochi secondi. Solo la console può mostrarle.",
"rpg_pair_title": "Associa questa app alla console",
"rpg_pair_body": "Connessione › Accendi e accedi › Configura. Un clic registra questa app sulla PS5 (come l'associazione dell'app PS Remote Play) e conserva le sue chiavi su questo computer. Streaming, riattivazione e accesso le usano tutti; ripeti dopo aver ripristinato la console o cambiato utente.",
"rpg_play_title": "Gioca",
"rpg_play_body": "Apri Remote Play e premi Avvia: l'app riattiva la console se è in riposo, esegue l'accesso e trasmette. Gioca con un controller collegato a questo computer, con la tastiera o col touch. Per usare invece l'app PS Remote Play di Sony o chiaki-ng, richiedi un PIN qui sotto e inseriscilo lì.",
"rpg_play_fix": "Apri Remote Play",
"rpg_title": "Configura Remote Play",
"rpg_progress": "{done} di {n} passaggi verificati completati",
"rpg_on_console": "verifica sulla console",
"rpg_trouble": "Se ancora non funziona",
"rpg_t_start_q": "Avvia è disattivato nella schermata Gioca.",
"rpg_t_start_a": "Questa app non è ancora associata a quella console: esegui il passaggio 6 (Connessione › Accendi e accedi › Configura).",
"rpg_t_pair_q": "La configurazione dell'associazione dice che non c'è un utente connesso con un account attivato.",
"rpg_t_pair_a": "Passaggi 1 e 2: accedi con un utente sulla PS5 e dagli un ID account, poi riprova.",
"rpg_t_grey_q": "L'impostazione Riproduzione Remota della PS5 stessa è disattivata (grigia).",
"rpg_t_grey_a": "L'account non ha effettuato l'accesso a PlayStation Network. Esegui l'accesso offline (passaggio 3) e riavvia la PS5.",
"rpg_t_wake_q": "La console non si riattiva, oppure si riattiva ma resta sulla schermata di selezione utente.",
"rpg_t_wake_a": "Controlla il passaggio 5 sulla console. Un utente con codice di accesso blocca l'accesso automatico. Se la console è stata ripristinata o l'utente è cambiato, configura di nuovo l'associazione (passaggio 6).",
"rpg_t_black_q": "L'immagine resta nera, scatta, o l'audio gracchia.",
"rpg_t_black_a": "Usa una connessione via cavo o il Wi-Fi a 5 GHz per la PS5 e questo computer, e prova 720p o 30 fps nelle impostazioni di Remote Play. Un firewall su questo computer deve consentire l'app sulla rete locale (Remote Play usa le porte TCP e UDP 9295–9304). In un browser usa un Chrome, Edge o Safari aggiornato: l'immagine richiede WebCodecs.",
"rpg_t_busy_q": "Dice che la PS5 sta ancora chiudendo l'ultima sessione, o che un'altra console sta trasmettendo.",
"rpg_t_busy_a": "Trasmette una console alla volta e la PS5 ha bisogno fino a 30 secondi dopo la fine di una sessione. Ferma l'altro stream, attendi un momento, poi premi di nuovo Avvia.",
"rpg_t_restrict_q": "Dopo l'accesso offline, i giochi chiedono di disattivare le restrizioni della console.",
"rpg_t_restrict_a": "Usa Annulla accesso in questa pagina e riavvia, oppure togli la restrizione in Impostazioni › Famiglia e filtro famiglia › Restrizioni della console PS5 (codice 0000 se non l'hai cambiato).",
