"mesh_rp_started": "{name} ha iniziato a giocare su questa console",
"rp_keys_body3": "Fai clic sull’immagine per giocare con la tastiera; Esc restituisce il puntatore. Doppio clic per lo schermo intero; lì Esc breve è Cerchio e tenere premuto Esc esce dallo schermo intero. Tasti, audio e altro in Impostazioni.",
"rp_play_description2": "Trasmetti una PS5 in questa app e gioca con controller, tastiera o touch. Riattiva da sola una console in modalità riposo e continua mentre usi altre schermate.",
