"dump_how": "I file del gioco vengono copiati in {folder}. Esistono solo mentre il gioco è in esecuzione, quindi viene avviato se non lo è; lascialo aperto finché il dump non termina.",
"dump_err_exists": "In quella cartella c'è già un dump di questo gioco. Eliminalo o rinominalo prima.",
