"send_title_v2": "Carica e installa",
"collection.send_many_body_v2": "Ogni PS5 riceve ciò che le manca: il pacchetto del gioco, oppure la sua cartella, immagine o archivio, più gli aggiornamenti più recenti e i DLC dei giochi che ha. I pacchetti vengono trasmessi da questo computer; il resto viene caricato sull'unità impostata in «Carica e installa», nella cartella homebrew.",
"first_run_step4_body_v3": "Inserisci nella PS5 una chiavetta USB con immagini di gioco .ffpkg e ShadowMount+ le monterà automaticamente — compariranno in Giochi. Per inviare altri file o installare pacchetti .pkg, usa «Carica e installa».",
"first_run_go_upload_v2": "Apri «Carica e installa»",
"fpkg.aboutFake_v2": "Il risultato è un pacchetto fake, quindi la console deve avere caricato il supporto ai pacchetti fake prima di installarlo: kstuff (la versione con supporto ai pacchetti fake PS5), a53_ppr_install_fast.elf e shadowmountplus.elf, in quest'ordine. «Carica e installa» dice la stessa cosa accanto ai suoi pulsanti di installazione.",
"fpkg.openUpload_v2": "Apri «Carica e installa»",
"connection_step3_hint_v3": "Apri «Carica e installa» e trascina una cartella di gioco, un'immagine .exfat o .ffpkg, o un pacchetto .pkg. Le immagini e le cartelle inviate compaiono nella pagina del gioco in Giochi, dove Monta le mette nella schermata Home della PS5.",
"connection_go_upload_v2": "Apri «Carica e installa»",
"netdoctor.speed_cap.on.fix_v2": "Togli il limite in «Carica e installa» se non ti serve.",
"payloads_fpkg_ppr_note_v2": "Per installare pacchetti fake serve anche a53_ppr_install_fast.elf, che non è in questo elenco: non ne è pubblicato alcun download e va compilato dal sorgente su GitHub. «Carica e installa» elenca tutto ciò che serve ai pacchetti fake, in ordine.",
"fs_extract_next_pkgs_v2": "Contiene {n} pacchetto/i: installali da «Carica e installa» o dalla loro riga qui.",
"game_hub_no_addons_v2": "Nessun pacchetto DLC preparato per questo titolo. Inviane uno da «Carica e installa».",
"game_hub_open_install_v2": "Apri «Carica e installa»",
"bandwidth_cap_off_hint_v3": "Nessun limite. Impostane uno se i caricamenti saturano il Wi-Fi/LAN e rallentano gli altri dispositivi. Vale per ogni caricamento, da «Carica e installa», dalla coda e da File, a partire dal prossimo.",
"queue_links_cleared_body_v2": "{n} link di installazione non sono stati conservati dopo il riavvio — i link non vengono mai salvati su disco. Aggiungili di nuovo da «Carica e installa».",
"game_hub_no_updates_v2": "Nessun pacchetto di aggiornamento preparato per questo titolo. Inviane uno da «Carica e installa».",
"pkglib.fpkgsupport.firmware": "I pacchetti fake PS5 (PS5 FPKG) non sono ancora supportati su firmware successivi alla 11.60: si installano, ma il gioco non si avvia. I pacchetti fake PS4 funzionano.",
"upload_drop_here3": "Trascina o scegli pacchetti, giochi, immagini disco, archivi o qualsiasi file",
"upload_pick_here_mobile3": "Scegli pacchetti, giochi, immagini disco, archivi o qualsiasi file",
"upload_drop_kind_pkg": "Pacchetti (.pkg, .fpkg): installati come gioco, aggiornamento o DLC, trasmessi da qui o caricati prima.",
"upload_drop_kind_game": "Cartelle di gioco e dump di giochi: copiati sulla PS5; possono andare nella schermata Home.",
"upload_drop_kind_image": "Immagini disco (.exfat, .ffpkg, .ffpfs, .ffpfsc): copiate sulla PS5; possono essere montate.",
"upload_drop_kind_archive": "Archivi (.zip, .7z, .rar): estratti sulla PS5.",
"upload_drop_kind_other": "Qualsiasi altro file o cartella: copiato così com'è.",
"upload_other_ways": "Oppure installa un pacchetto:",
"queue_stream_fail_hint": "Con «Trasmetti e installa» la PS5 preleva il pacchetto da questo computer. Se continua a non riuscire, consenti ps5upload nel firewall di questo computer sulla rete locale perché la PS5 possa raggiungerlo, oppure usa «Riprova con caricamento», che prima copia il pacchetto sulla PS5 e poi lo installa.",
"err_install_enoent_generic_v2": "L'installer di Sony non è riuscito ad aprire un file necessario durante l'installazione (errore del kernel 0x80020002 = ENOENT). Se è un pkg DLC, il gioco base non è ancora installato — installa prima la base. Altrimenti il pacchetto preparato potrebbe essere stato eliminato tra il caricamento e l'installazione; riprova l'installazione una volta. Se continua a non riuscire, installalo con «Trasmetti e installa» in «Carica e installa», che invia il pacchetto direttamente da questo computer invece di copiarlo prima sulla console.",
"upload_convert_first": "Converti prima",
"batch_convert_first_hint": "Apri i giochi, le cartelle e le immagini selezionati nell'Officina, per farne prima pacchetti, immagini o cartelle",
"add_sources_pick_folders": "Scegli una o più cartelle",
"add_sources_pick_files": "Scegli uno o più file",
"workshop_add_locked": "Si sta creando un gioco: i giochi scelti ora attendono in coda.",
"workshop_add_hint": "Scegli un gioco per controllarlo qui. Più giochi, o una cartella di giochi, vanno in coda e vengono creati uno dopo l'altro.",
"workshop_description_v2": "Cambia il formato di un gioco prima che vada sulla PS5: crea un pacchetto (.pkg), un'immagine di gioco (.exfat, .ffpkg o il più piccolo .ffpfsc) o una semplice cartella, oppure guarda dentro un'immagine o un pacchetto e modificane i file. Il lavoro si svolge su questo computer. Per inviare un gioco così com'è, usa {send}.",
"cq_title_v2": "⑤ Coda",
"cq_about": "Creati uno dopo l'altro su questo computer, ciascuno come erano impostati ②, ③ e ④ quando è stato aggiunto. Aggiungine altri in ①, anche mentre la coda è in corso; modifica un gioco in attesa con il suo pulsante delle opzioni.",
"cq_then_send": "Un gioco impostato per l'installazione o il caricamento passa alla coda di {send} una volta creato.",
"cq_open_send": "Apri {send}",
"backup_alike_toggle": "{count} copie uguali dal {since}. Mostrale per ripristinarne una più vecchia.",
"add_sources_no_picker": "Questa build non può sfogliare questo computer: digita un percorso visibile al motore.",
"collection.empty_body_v2": "Pacchetti, cartelle di gioco, immagini di gioco e archivi al suo interno vengono trovati e raggruppati per gioco. Nella cartella non viene modificato nulla. Va bene una cartella su questo dispositivo, un'unità esterna o una cartella su un NAS o server (SMB, FTP, SFTP, WebDAV).",
"collection.add_nas_folder": "Da un NAS o server",
"browse_this_device": "Questo dispositivo…",
"queue_added_waits_for_start": "Aggiunto alla coda: premi «Avvia coda» per eseguirlo",
"queue_added_waits_for_start_body": "«Avvia la coda quando aggiungi qualcosa» è disattivato, quindi non parte nulla finché non premi «Avvia coda».",
"queue_auto_start": "Avvia la coda quando aggiungi qualcosa",
"queue_auto_start_tooltip": "Attivo: «Installa», «Carica ora» e «Invia» avviano l'intera coda di questa console, in ordine. Disattivo: aggiungono solo alla coda, e non viene eseguito nulla finché non premi «Avvia coda».",
"queue_auto_start_hint": "Attivo: «Installa», «Carica ora» e «Invia» avviano l'intera coda della console, in ordine, non solo ciò che hai appena aggiunto. Disattivo: aggiungono solo alla coda, e non viene eseguito nulla finché non premi «Avvia coda». Attivo per impostazione predefinita.",
"queue_start_rest_tooltip": "Sono in esecuzione solo gli elementi che hai avviato. Questo esegue anche tutto ciò che è in attesa, nell'ordine della coda.",
